import assert from 'node:assert/strict';
import { mkdir, mkdtemp } from 'node:fs/promises';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { chromium } from 'playwright-core';
import { startDesktop } from '../../src/application.ts';
import { accountDataDirectory } from '../../src/accounts/account-managers.ts';
import { fixtureAuth, TEST_OWNER } from './auth.ts';
import { modelPort } from '../../../../packages/agentloop-local-runtime/tests/fixtures/models.ts';
import { seedMemory, seedRun } from './memory-inspection.ts';

// Explicit visual/interaction QA; all records and screenshots are temporary.
const root = await mkdtemp(join(tmpdir(), 'agentloop-memory-browser-'));
const skills = join(root, 'skills'); await mkdir(skills);
const dataDirectory = join(root, 'data');
const app = await startDesktop({ mode: 'development', port: 0, dataDirectory, models: modelPort(), cloudAuth: fixtureAuth(), bundledSkillDirectories: [skills], openBrowser: false });
assert.equal(app.existing, false);
let browser;
try {
  browser = await chromium.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  const page = await context.newPage(); const errors: string[] = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto(app.origin + '/memory'); await page.locator('#login:not([hidden])').waitFor();
  assert.equal(await page.locator('.item').count(), 0);
  await page.locator('#login').click(); await page.locator('#auth-submit:not([disabled])').waitFor();
  await page.locator('#auth-email').fill('test@example.test'); await page.locator('#auth-password').fill('fixture-only');
  await page.locator('#auth-submit').click(); await page.waitForURL(app.origin + '/memory*');
  await page.waitForFunction(() => document.getElementById('status')!.textContent!.includes('还没有记忆'));
  const account = accountDataDirectory(dataDirectory, TEST_OWNER);
  const saved = await seedMemory(account, TEST_OWNER); await seedRun(join(account, 'runtime.db'), TEST_OWNER);
  await page.locator('#refresh').click(); await page.locator('.item').waitFor();
  assert.equal(await page.locator('.item').count(), 1);
  assert.match(await page.locator('#memory-state').innerText(), /关闭.*历史记忆/);
  await page.locator('.item').click(); await page.locator('#detail .content').first().waitFor();
  assert.match(await page.locator('#detail').innerText(), /仅项目报告/);
  assert.equal(await page.evaluate(() => (window as any).memoryXss), undefined, 'memory markup must remain text');
  await page.getByRole('button', { name: '更多版本', exact: true }).click();
  await page.waitForFunction(() => document.querySelector('#detail .detail-section:last-child')!.querySelectorAll(':scope > details').length === 28);
  await page.locator('#query').fill('不存在的记忆'); await page.locator('#library-search button[type=submit]').click();
  await page.getByRole('heading', { name: '没有匹配的记忆' }).waitFor();
  await page.locator('#query').fill('中文'); await page.locator('#library-search button[type=submit]').click(); await page.locator('.item').waitFor();
  await page.locator('.item').click(); await page.locator('#detail .content').first().waitFor();
  await page.screenshot({ path: join(root, 'library-desktop.png'), fullPage: true });
  await page.setViewportSize({ width: 390, height: 900 });
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth), false);
  await page.screenshot({ path: join(root, 'library-mobile.png'), fullPage: true });
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.locator('[data-tab=jobs]').click(); await page.locator('.job').waitFor();
  assert.match(await page.locator('.job').innerText(), /重试耗尽.*invalid_output/s);
  await page.locator('.job button').click(); await page.locator('#run-evidence').waitFor();
  assert.equal(await page.locator('#run-evidence > details').count(), 20);
  await page.getByRole('button', { name: '继续加载执行证据' }).click();
  await page.waitForFunction(() => document.querySelectorAll('#run-evidence > details').length === 32);
  assert.match(await page.locator('#run-result').innerText(), /召回快照 · 1 条/);
  assert.match(await page.locator('#run-result').innerText(), /是否实际采用|实际采用情况/);
  const reviews = page.locator('.run-card').filter({ has: page.getByRole('heading', { name: '逐条采用复核', exact: true }) });
  assert.match(await reviews.innerText(), /无法判断/);
  assert.match(await reviews.innerText(), /效果未验证/);
  assert.match(await reviews.innerText(), /其执行支持已停止用于自动召回/);
  await reviews.locator('.detail-section > details > summary').first().click();
  assert.match(await reviews.innerText(), /does not establish adoption/);
  assert.equal(await page.evaluate(() => (window as any).reviewXss), undefined, 'review reasons must remain literal text');
  assert.equal((await reviews.innerText()).includes('foreign-private-review'), false);
  await page.locator('#run-result > .run-card').nth(1).locator('summary').click();
  assert.match(await page.locator('#run-result').innerText(), new RegExp(saved.projection!.id));
  await page.screenshot({ path: join(root, 'run-desktop.png'), fullPage: true });
  await page.reload(); await page.locator('#run-evidence').waitFor();
  assert.equal(await page.locator('#run-query').inputValue(), 'memory-run-0001');
  await page.setViewportSize({ width: 390, height: 900 });
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth), false);
  await page.evaluate(() => scrollTo(0, 0));
  await page.screenshot({ path: join(root, 'run-mobile.png') });
  await page.locator('#run-evidence').scrollIntoViewIfNeeded();
  await page.screenshot({ path: join(root, 'run-mobile-evidence.png') });
  await page.locator('#run-query').fill('missing-run'); await page.locator('#run-search button[type=submit]').click();
  await page.getByRole('heading', { name: '没有找到该 Run' }).waitFor();
  assert.deepEqual(errors, []);
  console.log(JSON.stringify({ passed: true, root, checks: ['login return', 'empty memory', 'search', 'literal markup', '28 revisions', 'settlement failure', 'recall versus adoption', '32 paginated events', 'reload', '390 and 1440 widths', 'no page errors'] }));
} finally { await browser?.close(); if (!app.existing) await app.close(); }
